def minEatingSpeed(piles, h):
    left, right = 1, max(piles)
    while left < right:
        mid = left + (right - left) // 2
        totalHours = sum((pile + mid - 1) // mid for pile in piles)
        if totalHours > h:
            left = mid + 1
        else:
            right = mid
    return left

def minEatingSpeed2(mat, h):
    left, right = 1, max(max(row) for row in mat)
    while left < right:
        mid = left + (right - left) // 2
        totalHours = sum(sum((cell + mid - 1) // mid for cell in row) for row in mat)
        if totalHours > h:
            left = mid + 1
        else:
            right = mid
    return left
