            std::vector<int> curr = q.front();
            q.pop();

            if (curr == destination) {
                return steps;
            }

            int x = curr[0];
            int y = curr[1];

            if (x > 0 && maze[x - 1][y] == 0) {
                maze[x - 1][y] = 1;
                q.push({x - 1, y});
            }

            if (x < rows - 1 && maze[x + 1][y] == 0) {
                maze[x + 1][y] = 1;
                q.push({x + 1, y});
            }

            if (y > 0 && maze[x][y - 1] == 0) {
                maze[x][y - 1] = 1;
                q.push({x, y - 1});
            }

            if (y < cols - 1 && maze[x][y + 1] == 0) {
                maze[x][y + 1] = 1;
                q.push({x, y + 1});
            }
        }

        steps++;
    }

    return -1;
}
