    std::string current;

    std::function<void(int)> backtrack = [&](int start) {
        if (start == s.size()) {
            result.push_back(current);
            return;
        }

        for (int end = start + 1; end <= s.size(); ++end) {
            std::string word = s.substr(start, end - start);
