                if (!current.empty()) {
                    current += " ";
                }
                current += word;
                backtrack(end);
                current.erase(current.size() - word.size());
                if (!current.empty()) {
                    current.pop_back();
                }
            }
        }
    };

    backtrack(0);
    return result;
}

