                int nextNode = edge[1];
                if (color[nextNode] == c) {
                    return false;
                }
                if (color[nextNode] == -1 && !dfs(nextNode, 1 - c, color, edges)) {
                    return false;
                }
            }
        }
        return true;
    }
}
