    int m = grid.size(), n = grid[0].size();
    vector<vector<int>> row(m, vector<int>(n + 1, 0));
    vector<vector<int>> col(m + 1, vector<int>(n, 0));

    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            row[i][j + 1] = row[i][j] + grid[i][j];
            col[i + 1][j] = col[i][j] + grid[i][j];
