        fast = fast.next.next

    mid = slow.next
    slow.next = None

    return merge(sortList(head), sortList(mid))

def merge(left, right):
    if not left:
        return right
    if not right:
        return left
    if left.val < right.val:
        left.next = merge(left.next, right)
        return left
    else:
        right.next = merge(left, right.next)
        return right

