def min_cost(costs: List[List[int]]) -> int:
    if not costs:
        return 0

    n, k = len(costs), len(costs[0])

    for i in range(1, n):
        for j in range(k):
            min_cost = float("inf")
            for l in range(k):
                if l == j:
                    continue
                min_cost = min(min_cost, costs[i - 1][l])
            costs[i][j] += min_cost

    return min(costs[n - 1])


def sliding_window_min(nums: List[int], k: int) -> List[int]:
    if not nums or k <= 0:
        return []

    result = []
    deque = []

    for i, num in enumerate(nums):
        while deque and nums[deque[-1]] >= num:
            deque.pop()
        deque.append(i)

        if deque[0] == i - k:
            deque.pop(0)

        if i >= k - 1:
            result.append(nums[deque[0]])

