    vector<int> closestKValues(TreeNode* root, double target, int k) {
        vector<int> result;
        stack<TreeNode*> s;
        TreeNode* node = root;
        while (node || !s.empty()) {
            while (node) {
                s.push(node);
                node = node->left;
            }
            node = s.top();
            s.pop();
            if (result.size() < k) {
                result.push_back(node->val);
            } else if (abs(target - result.back()) > abs(target - node->val)) {
                result.pop_back();
                result.push_back(node->val);
            } else {
                break;
            }
            node = node->right;
        }
        return result;
    }
};
