import heapq
from collections import Counter

def rearrange_string(s, k):
    if k == 0:
        return s

    counter = Counter(s)
    max_heap = [(-count, char) for char, count in counter.items()]
    heapq.heapify(max_heap)

    result = []
    while max_heap:
        temp = []

        for _ in range(k):
            if not max_heap:
                break

            count, char = heapq.heappop(max_heap)
            result.append(char)

            if count + 1 < 0:
                temp.append((count + 1, char))

        for item in temp:
            heapq.heappush(max_heap, item)

        if not max_heap:
            break

        if len(result) < len(s):
            result.extend([' '] * (k - len(temp)))

    if len(result) < len(s):
        return ""
    return "".join(result)

def task_scheduler(tasks, n):
    counter = Counter(tasks)
    max_heap = [(-count, task) for task, count in counter.items()]
    heapq.heapify(max_heap)

    result = []
    while max_heap:
        temp = []

        for _ in range(n + 1):
            if not max_heap:
                break

            count, task = heapq.heappop(max_heap)
            result.append(task)

            if count + 1 < 0:
                temp.append((count + 1, task))

        for item in temp:
            heapq.heappush(max_heap, item)

        if not max_heap:
            break

        if len(result) < len(tasks):
            result.extend([' '] * (n + 1 - len(temp)))

    if len(result) < len(tasks):
        return 0
    return len(result)

# Test case
tasks = ["A", "A", "A", "B", "B", "B"]
n = 2
print(task_scheduler(tasks, n))  # Output: 8
