def checkPerfectNumber(num: int) -> bool:
    if num <= 1:
        return False
    sum = 1
    i = 2
    while i * i <= num:
        if num % i == 0:
            sum += i
            if i * i != num:
                sum += num // i
        i += 1
    return sum == num

def findPerfectNumbers(left: int, right: int) -> list:
    perfect_numbers = []
    for num in range(left, right + 1):
        if checkPerfectNumber(num):
            perfect_numbers.append(num)
    return perfect_numbers
