        for j in range(n - 1, -1, -1):
            if i == m - 1 and j == n - 1:
                dp[i][j] = min(0, grid[i][j])
            elif i == m - 1:
                dp[i][j] = min(0, dp[i][j + 1] + grid[i][j])
            elif j == n - 1:
                dp[i][j] = min(0, dp[i + 1][j] + grid[i][j])
            else:
                dp[i][j] = min(0, max(dp[i + 1][j], dp[i][j + 1]) + grid[i][j])

