#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
#include <sstream>

struct Node {
    bool val;
    bool isLeaf;
    Node* topLeft;
    Node* topRight;
    Node* bottomLeft;
    Node* bottomRight;
};

Node* construct(vector<vector<int>>& grid) {
    return helper(grid, 0, 0, grid.size());
}

Node* helper(vector<vector<int>>& grid, int x, int y, int length) {
    if (length == 1) {
        return new Node{grid[x][y] == 1, true, nullptr, nullptr, nullptr, nullptr};
    }

    Node* tl = helper(grid, x, y, length / 2);
    Node* tr = helper(grid, x, y + length / 2, length / 2);
    Node* bl = helper(grid, x + length / 2, y, length / 2);
    Node* br = helper(grid, x + length / 2, y + length / 2, length / 2);

    if (tl->isLeaf && tr->isLeaf && bl->isLeaf && br->isLeaf &&
        tl->val == tr->val && tr->val == bl->val && bl->val == br->val) {
        bool value = tl->val;
        delete tl;
        delete tr;
        delete bl;
        delete br;
        return new Node{value, true, nullptr, nullptr, nullptr, nullptr};
    } else {
        return new Node{false, false, tl, tr, bl, br};
    }
}

vector<string> evaluateExpression(string expression, vector<string>& evalvars, vector<int>& evalints) {
    unordered_map<string, int> varMap;
    for (int i = 0; i < evalvars.size(); i++) {
        varMap[evalvars[i]] = evalints[i];
    }

    vector<string> tokens;
    stringstream ss(expression);
    string token;
    while (ss >> token) {
        tokens.push_back(token);
    }

    vector<string> result;
    for (int i = 0; i < tokens.size(); i++) {
        if (varMap.find(tokens[i]) != varMap.end()) {
            result.push_back(to_string(varMap[tokens[i]]));
        } else {
            result.push_back(tokens[i]);
        }
    }

    return result;
}

int main() {
    vector<vector<int>> grid = {{1, 1}, {1, 0}};
    Node* root = construct(grid);

    vector<string> evalvars = {"e"};
    vector<int> evalints = {1};
    vector<string> result = evaluateExpression("e + 8 - a + 5", evalvars, evalints);

    for (string s : result) {
        cout << s << endl;
    }

    return 0;
}
